public class InnerMemoryUserPreferenceOverrideFactory(Action<Humidifier.BedrockAgentCore.MemoryTypes.UserPreferenceOverride> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.MemoryTypes.UserPreferenceOverride>
{

    internal InnerMemoryUserPreferenceOverrideConsolidationConfigurationInputFactory ConsolidationFactory { get; set; }

    internal InnerMemoryUserPreferenceOverrideExtractionConfigurationInputFactory ExtractionFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.MemoryTypes.UserPreferenceOverride Create()
    {
        var userPreferenceOverrideResult = CreateUserPreferenceOverride();
        factoryAction?.Invoke(userPreferenceOverrideResult);

        return userPreferenceOverrideResult;
    }

    private Humidifier.BedrockAgentCore.MemoryTypes.UserPreferenceOverride CreateUserPreferenceOverride()
    {
        var userPreferenceOverrideResult = new Humidifier.BedrockAgentCore.MemoryTypes.UserPreferenceOverride();

        return userPreferenceOverrideResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.MemoryTypes.UserPreferenceOverride result)
    {
        base.CreateChildren(result);

        result.Consolidation ??= ConsolidationFactory?.Build();
        result.Extraction ??= ExtractionFactory?.Build();
    }

} // End Of Class

